 "content": "from collections import Counter


def transform(grid):
    """Copy the embedded three-cell line over each isolated marker, centered on it."""
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    nonbackground = Counter(v for row in grid for v in row if v != background)
    marker = nonbackground.most_common(1)[0][0]

    # Locate a straight, contiguous three-cell source line, excluding the
    # background and favoring cells that are not the repeated marker color.
    candidates = []
    for r in range(h):
        for c in range(w - 2):
            vals = [grid[r][c + k] for k in range(3)]
            if all(v != background for v in vals):
                candidates.append((sum(v != marker for v in vals), r, c, 0, vals))
    for r in range(h - 2):
        for c in range(w):
            vals = [grid[r + k][c] for k in range(3)]
            if all(v != background for v in vals):
                candidates.append((sum(v != marker for v in vals), r, c, 1, vals))
    if not candidates:
        return [row[:] for row in grid]
    _, sr, sc, orient, vals = max(candidates, key=lambda x: x[0])

    out = [row[:] for row in grid]
    anchors = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    for r, c in anchors:
        for k, value in enumerate(vals):
            rr, cc = (r, c + k - 1) if orient == 0 else (r + k - 1, c)
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = value
    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
